// Rules built for the built-in decks (goldfish/static/decks): stax and tax pieces, conditional bonuses, cost changes, cascade, populate, devour,
// encore, prepared spells, sneak, meld, level up, station, and about a hundred single-card lines. Every card comes from the set database.
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', '..');
const G = require(path.join(ROOT, 'goldfish', 'static', 'sim.js'));
const D = path.join(ROOT, 'goldfish', 'static', 'data', 'sets');
const idx = JSON.parse(fs.readFileSync(path.join(D, 'index.json'), 'utf8')), store = {};
idx.sets.forEach(s => { store[s.code] = JSON.parse(fs.readFileSync(path.join(D, (/^(con|prn|aux|nul|com\d|lpt\d)$/i.test(s.code) ? s.code + '_' : s.code) + '.json'), 'utf8')); });
const find = n => { for (const f of Object.values(store)) { const c = f.cards.find(x => (x.name === n || x.name.split(' // ')[0] === n) && !x.ref); if (c) return Object.assign({}, c, { qty: 1 }); } throw new Error('not in the database: ' + n); };
const base = JSON.parse(fs.readFileSync(path.join(ROOT, 'tests', 'fixtures', 'red-rum-raiders-loaded.json'), 'utf8'));
const NAMES = ['Sphere of Resistance', 'Thalia, Guardian of Thraben', 'Stony Silence', 'Torpor Orb', 'Rest in Peace', "Grafdigger's Cage", 'Mana Breach', 'Favorable Winds', 'Hand of the Praetors', 'Jodah, the Unifier',
  'Hallowed Haunting', 'Voice of the Blessed', 'Primordial Hydra', 'Steel of the Godhead', 'Renata, Called to the Hunt', 'Dracogenesis', 'The Ur-Dragon', 'Zimone, Infinite Analyst', "Sephara, Sky's Blade", 'Path of Annihilation',
  'Metalworker', 'Coralhelm Commander', 'Ixhel, Scion of Atraxa', 'Alandra, Sky Dreamer', 'Angel of Indemnity', 'Animation Module', "Animist's Awakening", 'Open the Way', 'Azlask, the Swelling Scourge', 'Benevolent Hydra',
  'Bloodspore Thrinax', 'Bramble Sovereign', 'Bruna, the Fading Light', 'Cosmogrand Zenith', 'Devilish Valet', 'Displacer Kitten', 'Eldrazi Displacer', "Dragon's Hoard", 'Fertilid', 'Fountainport', 'Fractal Harness',
  'Ghalta and Mavren', 'Ghave, Guru of Spores', 'Gisela, the Broken Blade', 'Celestial Colonnade', 'Inkmoth Nexus', 'Grove of the Guardian', 'Growing Ranks', 'Trostani, Selesnya\'s Voice', 'Guide of Souls', 'Halo Fountain',
  'Haven of the Spirit Dragon', 'Hermit Druid', 'Inscription of Abundance', 'Jadzi, Steward of Fate // Oracle\'s Gift', 'Striding Shotcaller // Run the Play', 'Zhulodok, Void Gorger', 'Quandrix, the Proof', 'Kenrith, the Returned King',
  'Skithiryx, the Blight Dragon', 'Kuldotha Forgemaster', 'Lathiel, the Bounteous Dawn', 'Llanowar Reborn', 'Mantle of the Ancients', 'Mathemagics', 'Mazemind Tome', 'Outpost Siege', 'Planar Bridge', 'Polukranos, Unchained',
  'Primo, the Unbounded', 'Shadrix Silverquill', 'Tainted Pact', 'Tanazir Quandrix', 'The Goose Mother', "The Last Ronin's Technique", 'The Soul Stone', 'Tiamat', 'Tinybones, Pocket Nuisance', 'Tinybones, Trinket Thief',
  'Torrential Gearhulk', 'Training Grounds', 'Ulamog, the Defiler', 'Unbound Flourishing', 'Uthros, Titanic Godcore', 'Verdurous Gearhulk', 'World Breaker', 'Xolatoyac, the Smiling Flood', "Yawgmoth's Will", 'Karn, Scion of Urza',
  'Aminatou, the Fateshifter', 'Glacial Chasm', "Estrid's Invocation", 'Oblivion Ring', 'Winding Constrictor', 'Enchanted Evening', 'Song of the Worldsoul',
  'Laboratory Maniac', 'Jace, Wielder of Mysteries', 'Rankle, Master of Pranks', 'Possessed Portal', 'Tandem Lookout', 'Citadel Siege', 'Devoted Druid', 'Tekuthal, Inquiry Dominus', "Kiora's Follower", 'Deathrite Shaman', 'Expressive Iteration', 'Fact or Fiction', 'Sokenzan, Crucible of Defiance', "Thespian's Stage", 'Arena of Glory', 'Hooded Hydra', "Urza's Saga", 'Ancient Tomb',
  // helpers
  'Grave Titan', 'Sol Ring', 'Lightning Bolt', 'Arcane Signet', 'Mind Stone', 'Llanowar Elves', 'Birds of Paradise', 'Serra Angel', 'Kiki-Jiki, Mirror Breaker', 'Rhystic Study', 'Rancor', 'Swiftfoot Boots', 'Wastes', 'Forest', 'Island', 'Opt', 'Ulamog, the Ceaseless Hunger', 'Shivan Dragon', 'Plague Stinger'];
const extra = [];
for (const n of NAMES) { if (base.cards.some(c => c.name === n)) continue; extra.push(find(n)); }
const cards = base.cards.filter(c => !NAMES.includes(c.name)).slice(0, 30).concat(base.cards.filter(c => NAMES.includes(c.name))).concat(extra);
const deck = G.buildDeck(cards, base.tokens);
const O = { turns: 20, onPlay: false, minLands: 2, maxLands: 5, freeMulligan: true, minHandSize: 5, oppLife: 40, prioritizeCommander: true };
let pass = 0, fail = 0;
const check = (n, ok, d) => { (ok ? pass++ : fail++); console.log((ok ? 'PASS' : 'FAIL') + '  ' + n + (d !== undefined ? '   [' + d + ']' : '')); };
const by = n => { const c = deck.unique.find(c => c.name === n || c.name.split(' // ')[0] === n); if (!c) throw new Error('card not in the test deck: ' + n); return c; };
const has = n => deck.unique.some(c => c.name === n || c.name.split(' // ')[0] === n);
const bare = seed => { const g = G.newGame(deck, O, seed || 3); g.turn = 6; g.hand = []; g.battlefield = []; g.graveyard = []; g.exile = []; g.command = []; g.library = g.library.slice(0, 40); return g; };
const mirror = () => { const g = bare(3), b = bare(4); G.linkMatch(g, b); return { g, b }; };
const putOn = (g, n, o) => { const p = G.enterWithTriggers(g, { iid: g.nextIid++, card: by(n) }, o || {}, []); p.sick = false; p.tapped = false; p.enteredTurn = 1; return p; };
const inst = (g, n) => ({ iid: g.nextIid++, card: by(n) });
const mana = (g, n, c) => { for (let i = 0; i < n; i++) g.floating.push({ src: null, colors: new Set(c ? [c] : ['W', 'U', 'B', 'R', 'G', 'C']), floating: true }); };
const total = c => c.generic + c.pips.length;
const tok = (name, p, t) => ({ type: 'token', n: 1, creature: true, p, t, colors: [], subtypes: [name], keywords: [], artifact: false, name });
const T = (name, fn) => { try { fn(); } catch (e) { check(name + ' (threw)', false, String(e && e.stack || e).split('\n').slice(0, 3).join(' | ')); } };

// ---- every line of these cards is read
{ const bad = []; for (const n of NAMES.slice(0, NAMES.indexOf('Grave Titan'))) { if (!has(n)) continue; const c = by(n); for (const x of [c].concat(c.a.backCard ? [c.a.backCard] : [])) for (const v of x.a.coverage) if (v.status === 'ignored') bad.push(n + ': ' + v.text.slice(0, 50)); }
  check('every rules line of these cards is read', bad.length === 0, bad.slice(0, 4).join(' || ')); }

// ---- group A: taxes, stax, conditional bonuses, costs
T('taxes', () => { const g = bare(); const b = inst(g, 'Lightning Bolt'), t = inst(g, 'Grave Titan'); g.hand = [b, t]; putOn(g, 'Sphere of Resistance'); putOn(g, 'Thalia, Guardian of Thraben');
  check('Sphere of Resistance and Thalia: a noncreature spell costs 2 more, a creature spell 1 more', total(G.effectiveCost(g, b)) === 3 && total(G.effectiveCost(g, t)) === 7, `${total(G.effectiveCost(g, b))}, ${total(G.effectiveCost(g, t))}`); });
T('stony', () => { const g = bare(); const sr = putOn(g, 'Sol Ring'); putOn(g, 'Llanowar Elves'); const n0 = G.manaUnits(g).length; putOn(g, 'Stony Silence'); check('Stony Silence: artifacts make no mana', n0 === 3 && G.manaUnits(g).length === 1 && !G.manaUnits(g).some(u => u.src === sr), G.manaUnits(g).length); });
T('torpor', () => { const g = bare(); putOn(g, 'Torpor Orb'); putOn(g, 'Grave Titan'); check("Torpor Orb: a creature's enters ability does not trigger", g.battlefield.filter(p => p.token).length === 0); });
T('rip', () => { const { g, b } = mirror(); g.graveyard = [inst(g, 'Sol Ring')]; b.graveyard = [inst(b, 'Sol Ring')]; putOn(g, 'Rest in Peace'); check('Rest in Peace exiles every graveyard when it enters', g.graveyard.length === 0 && b.graveyard.length === 0 && g.exile.length === 1);
  g.graveyard.push(inst(g, 'Opt')); G.endTurn(g); check('...and what is put there later', g.graveyard.length === 0); });
T('cage', () => { const g = bare(); putOn(g, "Grafdigger's Cage"); g.graveyard = [inst(g, 'Grave Titan')]; G.applyEffects(g, [{ type: 'reanimate', from: 'own' }], null, [], null); check("Grafdigger's Cage stops reanimation", !g.battlefield.some(p => p.card.name === 'Grave Titan')); });
T('breach', () => { const g = bare(); putOn(g, 'Mana Breach'); const l = putOn(g, 'Island'); mana(g, 1); const b = inst(g, 'Lightning Bolt'); g.hand = [b]; G.castCard(g, b, true); check('Mana Breach: casting a spell returns a land to your hand', g.hand.some(i => i.card.name === 'Island') && !g.battlefield.includes(l)); });
T('winds', () => { const g = bare(); const a = putOn(g, 'Serra Angel'), t = putOn(g, 'Grave Titan'); const p0 = G.powerOf(g, a); putOn(g, 'Favorable Winds'); check('Favorable Winds: creatures with flying get +1/+1, others do not', G.powerOf(g, a) === p0 + 1 && G.powerOf(g, t) === 6); });
T('praetors', () => { const g = bare(); const h = putOn(g, 'Hand of the Praetors'), s = putOn(g, 'Plague Stinger'); check('Hand of the Praetors: other creatures with infect get +1/+1', G.powerOf(g, s) === 2 && G.powerOf(g, h) === 3, `${G.powerOf(g, s)}, ${G.powerOf(g, h)}`);
  mana(g, 2); const c = inst(g, 'Plague Stinger'); g.hand = [c]; G.castCard(g, c, true); check('...and casting a creature with infect gives a poison counter', g.poisonDealt === 1, g.poisonDealt); });
T('jodah', () => { const g = bare(); const j = putOn(g, 'Jodah, the Unifier'), k = putOn(g, 'Kiki-Jiki, Mirror Breaker'), t = putOn(g, 'Grave Titan'); check('Jodah: legendary creatures get +X/+X for each legendary creature', G.powerOf(g, j) === 5 + 2 && G.powerOf(g, k) === 2 + 2 && G.powerOf(g, t) === 6, `${G.powerOf(g, j)}, ${G.powerOf(g, k)}`); });
T('jodah cascade', () => { const g = bare(); putOn(g, 'Jodah, the Unifier'); const k = inst(g, 'Kiki-Jiki, Mirror Breaker'); g.hand = [k]; mana(g, 5); g.library = [inst(g, 'Lightning Bolt'), inst(g, 'Grave Titan'), inst(g, 'Thalia, Guardian of Thraben'), inst(g, 'Sol Ring')]; G.castCard(g, k, true);
  check('Jodah: a legendary spell from hand finds a cheaper legendary card and casts it for free', g.battlefield.some(p => p.card.name === 'Thalia, Guardian of Thraben') && g.library.length === 3, g.battlefield.map(p => p.card.name).join(', ')); });
T('haunting', () => { const g = bare(); const t = putOn(g, 'Grave Titan'); putOn(g, 'Hallowed Haunting'); putOn(g, 'Forest'); putOn(g, 'Island'); check('Hallowed Haunting: no flying with fewer than seven enchantments', !G.hasKw(g, t, 'flying')); putOn(g, 'Enchanted Evening'); check('...Enchanted Evening makes every permanent an enchantment: flying and vigilance', G.hasKw(g, t, 'flying') && G.hasKw(g, t, 'vigilance'), g.battlefield.length); });
T('voice', () => { const g = bare(); const v = putOn(g, 'Voice of the Blessed'); check('Voice of the Blessed: flying and vigilance at four counters', !G.hasKw(g, v, 'flying')); v.counters = 4; check('...Voice has flying and vigilance at four counters', G.hasKw(g, v, 'flying') && G.hasKw(g, v, 'vigilance')); });
T('hydra', () => { const g = bare(); const h = putOn(g, 'Primordial Hydra'); h.counters = 5; G.beginTurn(g); check('Primordial Hydra doubles its counters each upkeep and has trample at ten', h.counters === 10 && G.hasKw(g, h, 'trample'), h.counters); });
T('steel', () => { const g = bare(); const a = putOn(g, 'Serra Angel'); const st = putOn(g, 'Steel of the Godhead'); st.attachedTo = a.iid; G.touch(g); check('Steel of the Godhead on a white creature: +1/+1 and lifelink', G.powerOf(g, a) === 5 && G.hasKw(g, a, 'lifelink'), G.powerOf(g, a)); });
T('renata', () => { const g = bare(); const r = putOn(g, 'Renata, Called to the Hunt'); putOn(g, 'Llanowar Elves'); check("Renata's power is your devotion to green", G.powerOf(g, r) === 3, G.powerOf(g, r)); });
T('dracogenesis', () => { const g = bare(); const d = inst(g, 'Shivan Dragon'), t = inst(g, 'Grave Titan'); g.hand = [d, t]; putOn(g, 'Dracogenesis'); check('Dracogenesis: Dragon spells are free, other spells are not', total(G.effectiveCost(g, d)) === 0 && total(G.effectiveCost(g, t)) === 6); });
T('eminence', () => { const dk = G.buildDeck(cards.map(c => Object.assign({}, c, { commander: c.name === 'The Ur-Dragon' })), base.tokens); const g = G.newGame(dk, O, 3); const d = g.library.concat(g.hand).find(i => i.card.name === 'Shivan Dragon'), t = g.library.concat(g.hand).find(i => i.card.name === 'Grave Titan');
  check('The Ur-Dragon in the command zone: other Dragon spells cost {1} less', total(G.effectiveCost(g, d)) === 5 && total(G.effectiveCost(g, t)) === 6, total(G.effectiveCost(g, d))); });
T('ur-dragon attack', () => { const g = bare(); putOn(g, 'The Ur-Dragon'); putOn(g, 'Shivan Dragon'); g.library = g.library.slice(0, 20); g.hand = [inst(g, 'Grave Titan')]; G.combat(g); check('The Ur-Dragon: draw a card for each attacking Dragon, then put a permanent from hand onto the battlefield', g.hand.length === 2 && g.battlefield.some(p => p.card.name === 'Grave Titan') || g.battlefield.length >= 3, `hand ${g.hand.length}, bf ${g.battlefield.map(p => p.card.name).join(',')}`); });
T('zimone', () => { const g = bare(); const z = putOn(g, 'Zimone, Infinite Analyst'); z.counters = 3; const m = inst(g, 'Mathemagics'); m.extraX = 2; g.hand = [m]; const c0 = total(G.effectiveCost(g, m)); z.counters = 0; const c1 = total(G.effectiveCost(g, m)); z.counters = 3; g.xCastTurn = g.turn; const c2 = total(G.effectiveCost(g, m));
  check('Zimone: the first X spell each turn costs {1} less for each counter on her', c1 - c0 === 3 && c2 === c1, `${c1} -> ${c0}, second X spell ${c2}`); });
T('sephara', () => { const g = bare(); for (let i = 0; i < 4; i++) putOn(g, 'Serra Angel'); const s = inst(g, "Sephara, Sky's Blade"); g.hand = [s]; check("Sephara: {W} and four untapped fliers instead of her mana cost", total(G.effectiveCost(g, s)) === 1); mana(g, 1, 'W'); G.castCard(g, s);
  check('...the four fliers are tapped', g.battlefield.some(p => /Sephara/.test(p.card.name)) && g.battlefield.filter(p => p.card.name === 'Serra Angel' && p.tapped).length === 4); });
T('path', () => { const g = bare(); const u = putOn(g, 'Ulamog, the Ceaseless Hunger'), t = putOn(g, 'Grave Titan'); putOn(g, 'Path of Annihilation'); const us = G.manaUnits(g); check('Path of Annihilation: Eldrazi tap for mana of any color', us.some(x => x.src === u) && !us.some(x => x.src === t)); });
T('metalworker', () => { const g = bare(); const m = putOn(g, 'Metalworker'); g.hand = [inst(g, 'Sol Ring'), inst(g, 'Mind Stone'), inst(g, 'Lightning Bolt')]; check('Metalworker: {C}{C} for each artifact card in your hand', G.manaUnits(g).filter(u => u.src === m).length === 4, G.manaUnits(g).filter(u => u.src === m).length); });
T('level', () => { const g = bare(); const c = putOn(g, 'Coralhelm Commander'); check('Coralhelm Commander starts as a 2/2', G.powerOf(g, c) === 2); mana(g, 4); for (let i = 0; i < 6; i++) G.useAbilities(g); check('...levels up to level 4: a 4/4', c.level === 4 && G.powerOf(g, c) === 4 && G.toughnessOf(g, c) === 4, `level ${c.level}, ${G.powerOf(g, c)}/${G.toughnessOf(g, c)}`); });
T('toxic', () => { check('Ixhel: "Flying, vigilance, toxic 2" is read as keywords plus toxic', by('Ixhel, Scion of Atraxa').a.toxic === 2 && by('Ixhel, Scion of Atraxa').a.kw.has('flying') && by('Ixhel, Scion of Atraxa').a.kw.has('vigilance')); });

// ---- groups B and C
T('alandra', () => { const g = bare(); const a = putOn(g, 'Alandra, Sky Dreamer'); g.library = g.library.slice(0, 30); g.drawnTurnN = 0; const p0 = G.powerOf(g, a); G.draw(g, 5, []); check('Alandra: the fifth card of the turn gives +X/+X for the cards in hand', G.powerOf(g, a) === p0 + 5, `${p0} -> ${G.powerOf(g, a)}`); });
T('indemnity', () => { const g = bare(); g.graveyard = [inst(g, 'Sol Ring'), inst(g, 'Grave Titan'), inst(g, 'Rhystic Study')]; putOn(g, 'Angel of Indemnity'); check('Angel of Indemnity returns a permanent of mana value 4 or less', g.battlefield.some(p => p.card.name === 'Rhystic Study') && !g.battlefield.some(p => p.card.name === 'Grave Titan'));
  const g2 = bare(); const a = inst(g2, 'Angel of Indemnity'); g2.graveyard = [a]; mana(g2, 8); g2.combatDone = false; G.useAbilities(g2); const tk = g2.battlefield.find(p => p.card.name === 'Angel of Indemnity');
  check('Encore: a hasty token copy that is sacrificed at the end of the turn', !!tk && tk.token && !tk.sick && g2.exile.includes(a)); if (tk) { G.endTurn(g2); check('...the encore token is gone at the end of the turn', !g2.battlefield.includes(tk)); } });
T('module', () => { const g = bare(); putOn(g, 'Animation Module'); const t = putOn(g, 'Grave Titan'); mana(g, 1); G.addCounters(g, t, '+1/+1', 1, [], null); check('Animation Module: a counter on your creature, pay {1}: a Servo', g.battlefield.filter(p => p.card.name === 'Servo').length === 1); });
T('awakening', () => { const g = bare(); g.library = [inst(g, 'Forest'), inst(g, 'Sol Ring'), inst(g, 'Island'), inst(g, 'Grave Titan')]; g.xValue = 3; G.applyEffects(g, by("Animist's Awakening").a.spellFx, null, [], null); const ls = g.battlefield.filter(p => p.asLand);
  check("Animist's Awakening: lands among the top X enter tapped, the rest go to the bottom", ls.length === 2 && ls.every(p => p.tapped) && g.library.length === 2 && g.library[0].card.name === 'Grave Titan', ls.length);
  const g2 = bare(); g2.graveyard = [inst(g2, 'Opt'), inst(g2, 'Lightning Bolt')]; g2.library = [inst(g2, 'Forest')]; g2.xValue = 1; G.applyEffects(g2, by("Animist's Awakening").a.spellFx, null, [], null); check('...untapped with spell mastery', g2.battlefield.some(p => p.asLand && !p.tapped)); });
T('open the way', () => { const g = bare(); g.library = [inst(g, 'Sol Ring'), inst(g, 'Forest'), inst(g, 'Grave Titan'), inst(g, 'Island'), inst(g, 'Wastes')]; g.xValue = 2; G.applyEffects(g, by('Open the Way').a.spellFx, null, [], null); check('Open the Way: reveal until X lands, they enter tapped', g.battlefield.filter(p => p.asLand && p.tapped).length === 2 && g.library.some(i => i.card.name === 'Wastes')); });
T('azlask', () => { const g = bare(); const a = putOn(g, 'Azlask, the Swelling Scourge'); const u = putOn(g, 'Ulamog, the Ceaseless Hunger'), t = putOn(g, 'Grave Titan'); G.leavePerm(g, t, []); G.flushLeaves(g, []); const x0 = g.experience || 0; G.leavePerm(g, u, []); G.flushLeaves(g, []); check('Azlask: an experience counter when a colorless creature dies, not a colored one', x0 === 0 && g.experience === 1, `${x0} -> ${g.experience}`); });
T('benevolent', () => { const g = bare(); const h = putOn(g, 'Benevolent Hydra'); const t = putOn(g, 'Grave Titan'); G.addCounters(g, t, '+1/+1', 1, [], null); const hc = h.counters || 0; G.addCounters(g, h, '+1/+1', 1, [], null); check('Benevolent Hydra: one more counter on other creatures, not on itself', t.counters === 2 && h.counters === hc + 1, `${t.counters}, ${h.counters - hc}`);
  h.counters = 3; t.counters = 0; G.useAbilities(g); check('...it moves a counter onto another creature (which gets two)', h.counters === 2 && t.counters === 2 && h.tapped, `${h.counters}, ${t.counters}`); });
T('thrinax', () => { const g = bare(); G.createTokens(g, tok('Goblin', 1, 1), 2, [], null); const th = putOn(g, 'Bloodspore Thrinax'); check('Bloodspore Thrinax devours two tokens for two counters', th.counters === 2 && g.battlefield.filter(p => p.token).length === 0, th.counters); const e = putOn(g, 'Llanowar Elves'); check('...and other creatures enter with that many counters', e.counters === 2, e.counters); });
T('sovereign', () => { const g = bare(); putOn(g, 'Bramble Sovereign'); mana(g, 2, 'G'); putOn(g, 'Serra Angel'); check('Bramble Sovereign: pay {1}{G} for a token copy of a creature that enters', g.battlefield.filter(p => p.card.name === 'Serra Angel').length === 2 && g.battlefield.some(p => p.card.name === 'Serra Angel' && p.token)); });
T('bruna', () => { const g = bare(); g.graveyard = [inst(g, 'Serra Angel'), inst(g, 'Grave Titan')]; const b = inst(g, 'Bruna, the Fading Light'); g.hand = [b]; mana(g, 7); G.castCard(g, b, true); check('Bruna, the Fading Light: casting her returns an Angel or Human from the graveyard', g.battlefield.some(p => p.card.name === 'Serra Angel') && !g.battlefield.some(p => p.card.name === 'Grave Titan')); });
T('zenith', () => { const tr = by('Cosmogrand Zenith').a.triggers; check('Cosmogrand Zenith: one "second spell" trigger with two modes', tr.length === 1 && tr[0].kinds.includes('secondSpell') && tr[0].fx[0].type === 'modal' && tr[0].fx[0].modes.length === 2, JSON.stringify(tr.map(t => [t.kinds, t.fx.map(f => f.type)]))); });
T('valet', () => { const g = bare(); const v = putOn(g, 'Devilish Valet'); const p0 = G.powerOf(g, v); putOn(g, 'Llanowar Elves'); check("Devilish Valet's power doubles when another creature enters", G.powerOf(g, v) === p0 * 2, `${p0} -> ${G.powerOf(g, v)}`); });
T('kitten', () => { const g = bare(); putOn(g, 'Displacer Kitten'); putOn(g, 'Grave Titan'); const z0 = g.battlefield.filter(p => p.token).length; mana(g, 1); const b = inst(g, 'Lightning Bolt'); g.hand = [b]; G.castCard(g, b, true); check('Displacer Kitten: a noncreature spell flickers a permanent (Grave Titan makes two more Zombies)', g.battlefield.filter(p => p.token).length === z0 + 2); });
